/* New Year 8 guided revision. These questions are not an exam. */
window.EXAM06_REVISION_BANK = {"english":[{"type":"mc","area":"Characters & relationships","q":"Who is selected to become the Receiver of Memory?","options":["Asher","Jonas","Gabriel","Fiona"],"answer":1,"explain":"Jonas is selected at the Ceremony of Twelve; this separates him from his friends.","hint":"Think about the child skipped during Assignments.","id":"en06r-001","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Characters & relationships","q":"What does the Giver provide that no ordinary citizen can access?","options":["Special food","Memories of the world before Sameness","A secret bicycle","New school subjects"],"answer":1,"explain":"His memories include love, pleasure, pain and history, giving Jonas wisdom.","id":"en06r-002","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Characters & relationships","q":"Why is Jonas’s father important to the novel’s ethical conflict?","options":["He becomes Chief Elder","He reveals what release actually involves","He discovers new colours","He teaches Asher to read"],"answer":1,"explain":"Jonas sees his father carry out release, exposing the gap between familiar language and reality.","id":"en06r-003","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Characters & relationships","q":"What does Gabriel most strongly represent in Jonas’s decision to leave?","options":["The value of obedience","A person Jonas loves and wants to protect","His ambition to become Chief Elder","An unwanted rival"],"answer":1,"explain":"Protecting Gabriel makes Jonas act on his developing compassion.","id":"en06r-004","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Characters & relationships","q":"Who was the earlier Receiver-in-training whose experiences revealed a problem with the system?","options":["Lily","Fiona","Rosemary","Larissa"],"answer":2,"explain":"Rosemary’s death and the release of her memories exposed the community’s inability to handle pain.","id":"en06r-005","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Characters & relationships","q":"How does Jonas’s relationship with the Giver change?","options":["They remain strangers","From teacher and pupil to a bond of trust and care","They become political rivals","They meet only at ceremonies"],"answer":1,"explain":"The Giver mentors Jonas and shares painful knowledge, building mutual care.","id":"en06r-006","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Themes & ideas","q":"Which is the central trade-off behind Sameness?","options":["Security and predictability versus freedom and difference","Luxury versus poverty","School versus employment","Family size versus age"],"answer":0,"explain":"The community reduces uncertainty and suffering by limiting individuality, choice and experience.","id":"en06r-007","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Themes & ideas","q":"What does the novel suggest about remembering painful events?","options":["Pain has no educational value","Memories can create wisdom and empathy","History should always be erased","Only happy memories matter"],"answer":1,"explain":"Jonas learns that pain and joy together shape judgement and compassion.","id":"en06r-008","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Themes & ideas","q":"Why does the community use precise language?","options":["Only to teach spelling","To standardise behaviour and shape how people think","To encourage creative slang","Because citizens speak different languages"],"answer":1,"explain":"Rules about words are one part of maintaining conformity.","id":"en06r-009","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Themes & ideas","q":"Why is the word “release” significant?","options":["It is a scientific name for rain","It softens and conceals a disturbing practice","It refers to school holidays","It means moving to a new class"],"answer":1,"explain":"This is a euphemism: a mild term hides the reality of killing.","id":"en06r-010","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Themes & ideas","q":"What does Jonas increasingly recognise about love?","options":["Love has no place in human relationships","Love involves deep human connection missing from his community","It is the same as liking food","It is forbidden everywhere beyond the community"],"answer":1,"explain":"The memories help Jonas see what has been sacrificed for order.","id":"en06r-011","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Themes & ideas","q":"Which theme best fits the removal of citizens’ choices about occupations?","options":["Identity and autonomy","Space exploration","Athletic competition","The value of money"],"answer":0,"explain":"Assigned careers remove the freedom to decide one’s own future.","id":"en06r-012","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Quotations & symbolism","q":"In Chapter 13, Jonas suggests people should be protected from “wrong choices”. What tension does this reveal?","options":["He has fully rejected all rules","He has internalised the community’s values while starting to question them","He is making a joke","He wants everyone to leave immediately"],"answer":1,"explain":"His language shows how deeply conformity shapes him even when he questions its cost.","id":"en06r-013","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Quotations & symbolism","q":"Why is red significant when Jonas first notices it?","options":["It marks danger only","It symbolises perception, difference and emerging feeling","It shows the seasons changing","It identifies the Chief Elder"],"answer":1,"explain":"The first colour opens a world of choice and individuality previously suppressed.","id":"en06r-014","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Quotations & symbolism","q":"What does the recurring sled most closely symbolise?","options":["School success","Memories and the possibility of an unfamiliar life","The power of the Elders","Jonas’s lost bicycle"],"answer":1,"explain":"The sled is linked to Jonas’s first memory and the uncertain final journey.","id":"en06r-015","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Quotations & symbolism","q":"Why are the many books in the Receiver’s room significant?","options":["They are prizes for perfect behaviour","They contrast restricted public knowledge with hidden history","They show that Jonas dislikes reading","They are all copies of the Book of Rules"],"answer":1,"explain":"The books symbolise knowledge withheld from the community.","id":"en06r-016","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Quotations & symbolism","q":"What is suggested by the repeated phrase “back and back and back”?","options":["The memory of a recent holiday","The apparently endless past and the weight of history","An instruction to walk backwards","The timing of a ceremony"],"answer":1,"explain":"Repetition conveys a history so distant it seems unchangeable.","id":"en06r-017","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Quotations & symbolism","q":"What is a sound interpretation of the music at the novel’s end?","options":["It proves every character survived","It may suggest hope, while leaving Jonas’s fate open to interpretation","It is an official community announcement","It is proof that Jonas returned home"],"answer":1,"explain":"The ending is deliberately ambiguous: several readings require supporting evidence.","id":"en06r-018","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"TEEL essay structure","q":"In TEEL, what should the Topic sentence do?","options":["Introduce an arguable idea that answers the prompt","Retell the whole plot","Copy a quote without comment","End with an unrelated fact"],"answer":0,"explain":"Topic identifies the main claim of the paragraph.","hint":"Ask: what am I trying to prove?","id":"en06r-019","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"TEEL essay structure","q":"What belongs in Explain, immediately after Topic?","options":["A new paragraph about another book","Develop why the idea matters and what Lowry suggests","A list of characters","Only the page number"],"answer":1,"explain":"Explain develops the claim before the supporting example.","hint":"Topic → Explain → Evidence → Link.","id":"en06r-020","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"TEEL essay structure","q":"What counts as strong Evidence in a literary paragraph?","options":["A specific event or brief quotation from the novel","A personal guess about the writer","A repeated claim without support","An unrelated movie fact"],"answer":0,"explain":"Specific textual evidence supports the explanation; paraphrased moments can be useful.","id":"en06r-021","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"TEEL essay structure","q":"A strong Link should…","options":["Introduce a brand-new topic","Connect the example back to the question and Lowry’s message","Repeat a quotation without analysis","Say “This is my paragraph”"],"answer":1,"explain":"Link closes the reasoning loop and answers the prompt.","id":"en06r-022","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"TEEL essay structure","q":"Build a TEEL paragraph about freedom. Put the four statements in the correct order.","blocks":["Evidence: At the Ceremony of Twelve, Elders assign every child a future role.","Explain: When leaders decide people’s futures, individuals lose control over their identities.","Topic: Lowry presents personal choice as essential to freedom.","Link: This invites readers to question whether order is worth sacrificing autonomy."],"answer":[2,1,0,3],"explain":"The correct sequence is Topic → Explain → Evidence → Link.","hint":"First state the claim, then develop it before providing a specific event.","id":"en06r-023","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"TEEL essay structure","q":"Build a TEEL paragraph about memory. Arrange the stages.","blocks":["Evidence: Jonas receives memories of sunshine, snow and war.","Link: Through these contrasts, Lowry questions the cost of suppressing the past.","Explain: Experiences of joy and suffering help individuals recognise what others feel.","Topic: Lowry shows that memories give people emotional understanding."],"answer":[3,2,0,1],"explain":"The explanation interprets the idea; the examples then support it.","id":"en06r-024","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"TEEL essay structure","q":"Which is the strongest Topic sentence for “How does Lowry present control”?","options":["The story is about Jonas.","Lowry shows that strict rules make people dependent on authority.","Jonas rides a bicycle.","The Giver has many books."],"answer":1,"explain":"It presents an arguable interpretation directly tied to the question.","id":"en06r-025","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"TEEL essay structure","q":"Which sentence best EXPLAINS the point “The community limits freedom”?","options":["The Elders make all the major decisions.","This removes personal autonomy, even when the decisions appear protective.","The Ceremony of Twelve is in December.","Jonas is Nineteen in his age group."],"answer":1,"explain":"It explains why the situation matters; it is not another isolated fact.","id":"en06r-026","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"TEEL essay structure","q":"Which is the weakest TEEL link?","options":["Lowry therefore challenges a society that values order above individual choice.","This suggests that safety can come at the expense of freedom.","I have now written a paragraph.","Readers are invited to weigh security against independence."],"answer":2,"explain":"A link should return to the argument, not talk about the act of writing.","id":"en06r-027","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Short passage analysis","q":"What does the aircraft incident reveal about the community?","options":["People routinely question authority","Citizens have been trained to respond quickly to commands","Nobody feels any anxiety","The community welcomes unexpected visitors"],"answer":1,"explain":"The instant obedience establishes the power of rules and shared fear.","hint":"Look at how people react, not just what the aircraft does.","passage":"Reading scene — Chapter 1 (paraphrased): After an unexpected aircraft passes overhead, everyone immediately obeys instructions to go indoors. Even the children know that disobedience can bring severe consequences.","id":"en06r-028","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Short passage analysis","q":"Which detail is strongest evidence of conformity?","options":["The aircraft has a pilot","All citizens obey the same urgent announcement","The river has a landing field","Jonas cycles home"],"answer":1,"explain":"The shared reaction supports an argument about social control.","passage":"Reading scene — Chapter 1 (paraphrased): After an unexpected aircraft passes overhead, everyone immediately obeys instructions to go indoors. Even the children know that disobedience can bring severe consequences.","id":"en06r-029","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Short passage analysis","q":"How does Lowry create suspense in the ceremony scene?","options":["By interrupting the established order and delaying the explanation","By describing a long journey","By introducing a new setting","By listing every job in detail"],"answer":0,"explain":"Readers share Jonas’s uncertainty because his name is deliberately skipped.","passage":"Reading scene — Chapter 8 (paraphrased): During the Ceremony, the Chief Elder calls the students in order but passes over Jonas’s number. He feels ashamed and the audience becomes uneasy. Later, she announces his unusual selection.","id":"en06r-030","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Short passage analysis","q":"Which is a justified inference about Jonas’s feelings?","options":["He enjoys embarrassing others","He worries that being skipped means he has failed","He knows exactly what is happening","He has already decided to leave"],"answer":1,"explain":"His shame follows from a culture where public conformity is expected.","passage":"Reading scene — Chapter 8 (paraphrased): During the Ceremony, the Chief Elder calls the students in order but passes over Jonas’s number. He feels ashamed and the audience becomes uneasy. Later, she announces his unusual selection.","id":"en06r-031","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Short passage analysis","q":"What literary technique is most important in the Receiver’s room description?","options":["Onomatopoeia","Contrast","Rhyme","A flashback"],"answer":1,"explain":"The room’s differences highlight unequal access to knowledge and authority.","passage":"Reading scene — Chapter 10 (paraphrased): Jonas enters the Receiver’s room and notices unusual furniture, an abundance of books and a speaker that can be turned off. These privileges are unavailable in ordinary homes.","id":"en06r-032","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Short passage analysis","q":"How could the books be used as evidence in a paragraph?","options":["They show the community shares all information","They represent knowledge restricted to a select few","They prove Jonas never reads","They identify the story as a biography"],"answer":1,"explain":"Interpret the physical object as a symbol and link it to the theme.","passage":"Reading scene — Chapter 10 (paraphrased): Jonas enters the Receiver’s room and notices unusual furniture, an abundance of books and a speaker that can be turned off. These privileges are unavailable in ordinary homes.","id":"en06r-033","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Short passage analysis","q":"Which contrast is most evident in Jonas’s first memories?","options":["Pleasure and sensory richness versus practical control","Technology versus medieval warfare","Childhood versus employment","Fame versus poverty"],"answer":0,"explain":"The pleasurable memories expose what efficiency has cost the citizens.","passage":"Reading scene — Chapter 11 (paraphrased): In his first memories, Jonas experiences snow and sunlight for the first time. He learns the community removed unpredictable weather because it was inconvenient.","id":"en06r-034","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Short passage analysis","q":"What would make the strongest TEEL Link about the snow memory?","options":["The snow is white.","The Giver has a bed.","Lowry suggests that eliminating discomfort can also eliminate wonder.","Jonas goes to training."],"answer":2,"explain":"The link moves from the example to the author’s wider message.","passage":"Reading scene — Chapter 11 (paraphrased): In his first memories, Jonas experiences snow and sunlight for the first time. He learns the community removed unpredictable weather because it was inconvenient.","id":"en06r-035","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Short passage analysis","q":"How does the battle scene contribute to the theme of memory?","options":["It shows all memories are pleasant","It shows pain can teach empathy and moral responsibility","It suggests the community is currently at war","It makes the book a historical documentary"],"answer":1,"explain":"His attempt to help another person reveals compassion developed through experience.","passage":"Reading scene — Chapter 15 (paraphrased): Jonas receives a memory of a battlefield. He witnesses wounded people and tries to help a dying boy, confronting suffering far beyond anything he has known.","id":"en06r-036","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Short passage analysis","q":"Which response moves beyond simply retelling the battle scene?","options":["Jonas sees people on the ground.","The memory is about a war.","Through distressing imagery, Lowry shows why understanding suffering matters for empathy.","Jonas is training with the Giver."],"answer":2,"explain":"Analysis explains technique, effect and message instead of only naming events.","passage":"Reading scene — Chapter 15 (paraphrased): Jonas receives a memory of a battlefield. He witnesses wounded people and tries to help a dying boy, confronting suffering far beyond anything he has known.","id":"en06r-037","source":"Original practice question based on supplied revision scope"},{"type":"short","area":"Quotations & symbolism","q":"Which narrative perspective follows Jonas closely but uses “he”?","answer":["third person","third-person","3rd person","third person limited","third-person limited","3rd person limited"],"explain":"Third-person limited narration uses “he” and follows Jonas’s perspective. First-person narration would use “I”.","hint":"Read the pronouns: “he” is a third-person narrator.","source":"New guided revision written response","id":"en06r-038"},{"type":"short","area":"Characters & relationships","q":"Who is the Nurturer who is also Jonas’s parent?","answer":["his father","jonas father","jonas' father","jonas's father","jonas' dad","jonas dad","his dad","father","dad"],"explain":"Jonas’s father works as a Nurturer and his actions reveal what release means. “Dad” and “father” identify the same person.","hint":"Think about the parent who works with newchildren.","source":"New guided revision written response","id":"en06r-039"},{"type":"short","area":"TEEL essay structure","q":"What does the T in TEEL stand for?","answer":["topic","topic sentence"],"explain":"The Topic sentence makes the paragraph’s central argument in response to the question.","hint":"The first sentence states what you are arguing.","source":"New guided revision written response","id":"en06r-040"},{"type":"short","area":"Quotations & symbolism","q":"What literary technique is the term “release” an example of?","answer":["euphemism","a euphemism"],"explain":"A euphemism replaces a harsh reality with a gentler-sounding term; release disguises killing.","hint":"It makes a disturbing reality sound less unpleasant.","source":"New guided revision written response","id":"en06r-041"}],"science":[{"type":"mc","area":"Cells & organelles","q":"What is a cell?","options":["The basic structural and functional unit of living organisms","A collection of unrelated minerals","A type of human organ","A disease-causing substance"],"answer":0,"explain":"All living things are composed of one or more cells.","id":"sc06r-001","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Cells & organelles","q":"Which pair is correctly classified?","options":["Bacterium: unicellular; human: multicellular","Bacterium: multicellular; human: unicellular","Mushroom: unicellular; ant: unicellular","Tree: unicellular; yeast: multicellular"],"answer":0,"explain":"Unicellular organisms consist of one cell; multicellular organisms consist of many cells.","id":"sc06r-002","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Cells & organelles","q":"Which structures are present in typical plant cells but absent from animal cells?","options":["Cell wall and chloroplasts","Mitochondria and cytoplasm","Nucleus and ribosomes","Cell membrane and mitochondria"],"answer":0,"explain":"Plant cells contain cellulose cell walls and many photosynthetic cells have chloroplasts.","id":"sc06r-003","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Cells & organelles","q":"What is the principal role of the nucleus?","options":["Controls cell activities and contains genetic material","Releases oxygen into blood","Stores the entire organism’s food","Makes the outer cell wall"],"answer":0,"explain":"The nucleus contains DNA and regulates many cell processes.","visual":"cell","id":"sc06r-004","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Cells & organelles","q":"The structures labelled C in the plant-cell sketch are green ovals. What are they?","options":["Chloroplasts","Lysosomes","Ribosomes","Nucleoli"],"answer":0,"explain":"Chloroplasts contain chlorophyll for photosynthesis.","visual":"cell","id":"sc06r-005","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Cells & organelles","q":"What do mitochondria do?","options":["Release usable energy through respiration","Store the cell’s chromosomes only","Control what passes through the nucleus","Produce all cell walls"],"answer":0,"explain":"Mitochondria are key sites of aerobic cellular respiration.","id":"sc06r-006","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Cells & organelles","q":"What is the role of ribosomes?","options":["Protein synthesis","Long-distance blood flow","Photosynthesis in humans","Storing excess urine"],"answer":0,"explain":"Ribosomes assemble proteins from amino acids.","id":"sc06r-007","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Cells & organelles","q":"Which organelle modifies, sorts and packages proteins?","options":["Golgi apparatus","Cell wall","Vacuole","Chloroplast"],"answer":0,"explain":"The Golgi apparatus processes and directs cell products.","id":"sc06r-008","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Cells & organelles","q":"What is a major role of the endoplasmic reticulum?","options":["Processing and transporting materials within cells","Converting animals into plants","Digesting food in the stomach","Forming an organism’s skeleton"],"answer":0,"explain":"Rough ER is involved with proteins; smooth ER with lipids and other tasks.","id":"sc06r-009","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Cells & organelles","q":"Which cell component controls what enters and leaves the cell?","options":["Cell membrane","Cytoplasm","Nucleus","Ribosome"],"answer":0,"explain":"The selectively permeable cell membrane regulates movement of substances.","id":"sc06r-010","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Cells & organelles","q":"A large permanent vacuole in a plant cell mainly helps with…","options":["Storage and maintaining turgor pressure","Making all proteins","Reading DNA","Producing light"],"answer":0,"explain":"Water in the vacuole helps keep many plant cells firm.","id":"sc06r-011","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Cells & organelles","q":"Lysosomes mainly contain enzymes that…","options":["Break down waste and worn-out cell materials","Provide green colour","Conduct electricity","Hold chromosomes"],"answer":0,"explain":"Lysosomes help digest unwanted or damaged materials inside cells.","id":"sc06r-012","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Cells & organelles","q":"Which description best fits most fungal cells?","options":["They have nuclei and cell walls, but no chloroplasts","They lack cell walls and nuclei","They are identical to photosynthetic plant cells","They all live as single independent cells"],"answer":0,"explain":"Fungal walls usually contain chitin and fungi do not photosynthesise.","id":"sc06r-013","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Microscopy & magnification","q":"Which microscope component is labelled A on the diagram?","options":["Eyepiece","Stage","Coarse focus knob","Mirror"],"answer":0,"explain":"The eyepiece is at the viewing end of the microscope.","visual":"microscope","id":"sc06r-014","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Microscopy & magnification","q":"What is the correct way to begin focusing a specimen?","options":["Start with the lowest-power objective","Start on the highest-power objective","Touch the lens to the slide","Use coarse focus while on the highest power"],"answer":0,"explain":"Low power provides a wider field of view and reduces collision risk.","id":"sc06r-015","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Microscopy & magnification","q":"The eyepiece magnifies 10× and the objective 40×. What is the total magnification?","answer":400,"explain":"Multiply eyepiece magnification by objective magnification: 10 × 40 = 400.","tolerance":1e-05,"hint":"Multiply the two powers.","unit":"×","id":"sc06r-016","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Microscopy & magnification","q":"Why should a prepared slide be held securely on the stage?","options":["To prevent movement and damage","To increase magnification automatically","To change a plant cell into an animal cell","To remove the coverslip"],"answer":0,"explain":"Secure, careful handling improves accuracy and safety.","id":"sc06r-017","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Digestion & dentition","q":"Which sequence describes the path of food through the human digestive system?","options":["Mouth → oesophagus → stomach → small intestine → large intestine","Mouth → stomach → lungs → heart","Mouth → large intestine → oesophagus → stomach","Mouth → liver → brain → intestine"],"answer":0,"explain":"Food passes through the alimentary canal in this order.","visual":"digestion","id":"sc06r-018","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Digestion & dentition","q":"What is the main role of the small intestine?","options":["Absorbing most digested nutrients","Pumping blood","Producing red blood cells","Storing faeces before elimination"],"answer":0,"explain":"Its villi increase surface area for absorption.","visual":"digestion","id":"sc06r-019","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Digestion & dentition","q":"What does the large intestine mainly absorb?","options":["Water and salts","Oxygen from the lungs","Light energy","Only proteins"],"answer":0,"explain":"It absorbs remaining water and helps form faeces.","id":"sc06r-020","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Digestion & dentition","q":"Why do incisors, canines and molars have different shapes?","options":["They are adapted for cutting, tearing and grinding","They are adapted for seeing colours","They perform the same task equally","They are randomly shaped"],"answer":0,"explain":"Tooth shape is related to its role in mechanical digestion.","visual":"teeth","id":"sc06r-021","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Digestion & dentition","q":"Which adaptation is most associated with many herbivores?","options":["Broad grinding molars and a longer digestive tract","Large tearing canines and short gut only","No teeth of any kind","A digestive system with no microbes"],"answer":0,"explain":"Plant material can be difficult to break down; grinding and microbial digestion help.","id":"sc06r-022","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Digestion & dentition","q":"Which statement about carnivores and omnivores is accurate?","options":["Carnivores often have tearing teeth; omnivores can process both animal and plant foods","All omnivores eat only grass","All carnivores lack stomachs","All herbivores have identical teeth"],"answer":0,"explain":"Diet is reflected in different tooth shapes and digestive adaptations.","id":"sc06r-023","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Static electricity & charges","q":"Which particles carry the negative and positive charges in an atom?","options":["Electrons negative; protons positive","Protons negative; neutrons positive","Electrons positive; protons negative","Neutrons negative; electrons neutral"],"answer":0,"explain":"Neutrons are neutral; electrons move during many charging processes.","visual":"atom","id":"sc06r-024","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Static electricity & charges","q":"A balloon rubbed against hair becomes charged mainly because…","options":["Electrons transfer between materials","New protons are created","Neutrons leave the nucleus","Electricity is destroyed"],"answer":0,"explain":"Frictional charging transfers electrons; overall charge is conserved.","id":"sc06r-025","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Static electricity & charges","q":"Which describes charging by induction?","options":["A charged object causes charges to redistribute without touching","A battery is added to a circuit","An object becomes charged only by melting","Particles disappear when rubbed"],"answer":0,"explain":"An electric field rearranges charges; grounding can leave a net charge.","id":"sc06r-026","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Static electricity & charges","q":"Why is copper a useful wire material?","options":["Free electrons allow charge to flow","It contains no atoms","It prevents any charge movement","It creates unlimited energy"],"answer":0,"explain":"Metals are good conductors; plastic coatings are used as insulators.","id":"sc06r-027","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Static electricity & charges","q":"Two objects have the same type of electric charge. They will generally…","options":["Repel","Attract","Merge into a larger atom","Become magnets automatically"],"answer":0,"explain":"Like electric charges repel; opposite charges attract.","id":"sc06r-028","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Circuits, series & parallel","q":"Which circuit is complete so that current can flow?","options":["A closed circuit","An open switch breaking the loop","A circuit missing the battery connection","Two separated wires"],"answer":0,"explain":"Current needs a continuous conducting path and a source of potential difference.","id":"sc06r-029","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Circuits, series & parallel","q":"What does a voltmeter measure and how is it connected?","options":["Potential difference; in parallel across a component","Current; in series","Resistance; in parallel while the circuit is powered","Temperature; in series"],"answer":0,"explain":"Voltage is measured in volts (V); a voltmeter is connected in parallel.","id":"sc06r-030","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Circuits, series & parallel","q":"What does an ammeter measure and how is it connected?","options":["Current; in series","Voltage; across a component","Energy; beside a battery","Resistance; across a powered circuit"],"answer":0,"explain":"Current is measured in amperes (A); ammeters go in series.","id":"sc06r-031","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Circuits, series & parallel","q":"In the series diagram, what happens if lamp 1 is removed?","options":["Lamp 2 also goes out","Lamp 2 stays on unchanged","Lamp 2 doubles its brightness automatically","The battery gains voltage"],"answer":0,"explain":"Removing a series lamp breaks the only path for current.","visual":"series","id":"sc06r-032","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Circuits, series & parallel","q":"In the parallel diagram, one branch lamp fails. What happens to the other branch?","options":["It can remain lit","It must always go out","Current in every branch becomes zero","The battery stops working instantly"],"answer":0,"explain":"Each parallel branch has its own complete path.","visual":"parallel","id":"sc06r-033","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Circuits, series & parallel","q":"In a simple series circuit, which quantity is the same through every component?","options":["Current","Voltage drop across each unequal resistor","Resistance of each component","Brightness"],"answer":0,"explain":"There is one path, so the same current flows through all series elements.","id":"sc06r-034","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Circuits, series & parallel","q":"In a parallel circuit, what is equal across the branches?","options":["Potential difference (voltage)","Current in every unequal branch","Resistance of every branch","Power used by every branch"],"answer":0,"explain":"Each branch connects across the same pair of supply nodes.","id":"sc06r-035","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Circuits, series & parallel","q":"Two series resistors are 4 Ω and 8 Ω. What is their total resistance?","answer":12,"explain":"Series resistance adds: 4 + 8 = 12 Ω.","tolerance":1e-05,"unit":"Ω","id":"sc06r-036","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Circuits, series & parallel","q":"A 12 V supply is connected across a 6 Ω resistor. Find the current using Ohm’s Law.","answer":2,"explain":"I = V ÷ R = 12 ÷ 6 = 2 A.","tolerance":1e-05,"hint":"Rearrange V = IR.","unit":"A","id":"sc06r-037","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Circuits, series & parallel","q":"A circuit has 3 A through a 5 Ω resistor. What voltage is across it?","answer":15,"explain":"V = I × R = 3 × 5 = 15 V.","tolerance":1e-05,"unit":"V","id":"sc06r-038","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Circuits, series & parallel","q":"On a graph with voltage on the vertical axis and current on the horizontal axis, the gradient of an Ohmic conductor is…","options":["Resistance","Current","Power only","Time"],"answer":0,"explain":"V = IR means the slope ΔV/ΔI equals resistance.","visual":"iv","id":"sc06r-039","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Circuits, series & parallel","q":"An I–V graph is curved rather than a straight line through the origin. It is…","options":["Non-Ohmic over the measured range","Always zero resistance","Necessarily a broken voltmeter","A constant-resistance component"],"answer":0,"explain":"A changing gradient means the ratio V/I is not constant.","visual":"iv","id":"sc06r-040","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Scientific investigations","q":"A student changes light intensity and measures plant growth. Which is the independent variable?","options":["Light intensity","Plant growth","Species if kept constant","The ruler used"],"answer":0,"explain":"The independent variable is deliberately changed.","id":"sc06r-041","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Scientific investigations","q":"In that plant investigation, what is the dependent variable?","options":["Plant growth measured","Light intensity","The pot material if kept constant","The date of the assessment"],"answer":0,"explain":"The dependent variable is what the student measures.","id":"sc06r-042","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Scientific investigations","q":"Which is a controlled variable in a fair test of light and growth?","options":["Water supplied to each plant","Amount of light changed","Change in plant height","The final conclusion"],"answer":0,"explain":"Keep other relevant factors the same so the light effect is clearer.","id":"sc06r-043","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Scientific investigations","q":"Which is the best hypothesis?","options":["If wire length increases, resistance will increase because charge faces more collisions","We looked at wires yesterday","The aim is to collect data","All graphs have a title"],"answer":0,"explain":"A hypothesis predicts a relationship and ideally includes scientific reasoning.","id":"sc06r-044","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Scientific investigations","q":"Which belongs in a scientific method?","options":["Numbered, repeatable steps in past tense and third person","A personal story about liking science","Only the final answer","An unrelated advertisement"],"answer":0,"explain":"Example: “The length of the wire was measured using a ruler.”","id":"sc06r-045","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Scientific investigations","q":"Which graph suits temperature measured every minute?","options":["Line graph","Pie chart of unrelated categories","Pictogram only","No graph is appropriate"],"answer":0,"explain":"Continuous variables changing over time are often best displayed with a line graph.","id":"sc06r-046","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Scientific investigations","q":"What is an outlier?","options":["A data point noticeably different from the overall pattern","The average of all values","The independent variable","The label on the x-axis"],"answer":0,"explain":"Investigate unusual data; do not delete it without justification.","id":"sc06r-047","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"Scientific investigations","q":"Arrange these parts of a useful conclusion in a logical order.","blocks":["Support the trend with measured data.","Say whether the evidence supports the hypothesis.","Mention a relevant limitation if necessary.","State the overall trend in the results."],"answer":[3,0,1,2],"explain":"Good conclusions describe patterns and use data rather than merely saying the experiment worked.","id":"sc06r-048","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Scientific investigations","q":"Which change best improves reliability?","options":["Repeat trials and compare results","Change several variables at once","Record only the best result","Use fewer measurements without reason"],"answer":0,"explain":"Repeated measurements reduce the impact of random variation.","id":"sc06r-049","source":"Original practice question based on supplied revision scope"},{"type":"short","area":"Cells & organelles","q":"Name the organelle responsible for most aerobic energy release.","answer":["mitochondrion","mitochondria","the mitochondria","the mitochondrion"],"explain":"Mitochondria are the major sites of aerobic respiration, releasing energy for cell activity.","hint":"The plural name ends in -dria.","source":"New guided revision written response","id":"sc06r-050"},{"type":"short","area":"Circuits, series & parallel","q":"What is the SI unit of resistance?","answer":["ohm","ohms","Ω","omega"],"explain":"Electrical resistance is measured in ohms (Ω); current in amperes and voltage in volts.","hint":"The symbol looks like a Greek capital omega.","source":"New guided revision written response","id":"sc06r-051"},{"type":"short","area":"Scientific investigations","q":"What type of variable is deliberately changed by the investigator?","answer":["independent variable","the independent variable","independent"],"explain":"The independent variable is the factor the investigator changes. The dependent variable is measured.","hint":"Think: which variable did the investigator control or change deliberately?","source":"New guided revision written response","id":"sc06r-052"}],"humanities":[{"type":"mc","area":"Japan: key events & terms","q":"Which term describes Japan’s restricted foreign relations under the Tokugawa shogunate?","options":["Sakoku","Meiji","Tenochtitlan","Encomienda"],"answer":0,"explain":"Sakoku refers to restrictive foreign-contact policies; some controlled trade continued.","id":"hu06r-001","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Japan: key events & terms","q":"Who led the American naval expedition that arrived in Japan in 1853?","options":["Commodore Matthew Perry","Hernán Cortés","Tokugawa Ieyasu","Moctezuma II"],"answer":0,"explain":"Perry’s ships pressured Japan to negotiate with the United States.","id":"hu06r-002","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Japan: key events & terms","q":"When did Commodore Perry first arrive with his ships?","options":["1853","1519","1868","1905"],"answer":0,"explain":"Perry arrived in 1853; the Treaty of Kanagawa followed in 1854.","id":"hu06r-003","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Japan: key events & terms","q":"What did the 1854 Treaty of Kanagawa help establish?","options":["Opening certain ports to American vessels and diplomatic contact","A Spanish empire in Japan","Japan’s immediate abolition of its emperor","An end to all international contact"],"answer":0,"explain":"It marked a shift away from prior restrictions and preceded wider commercial treaties.","id":"hu06r-004","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Japan: key events & terms","q":"What was the 1868 Meiji Restoration?","options":["A political transformation restoring formal imperial rule and accelerating reforms","The Spanish defeat of the Aztecs","The first appearance of Christianity in Japan","A treaty signed by Commodore Perry"],"answer":0,"explain":"The Meiji government implemented far-reaching changes to institutions and industry.","id":"hu06r-005","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Japan: key events & terms","q":"Which group held the main military-political authority in Tokugawa Japan?","options":["The shogunate","Spanish conquistadors","The United Nations","The Aztec Triple Alliance"],"answer":0,"explain":"The shogun led the military government; the emperor retained a different role.","id":"hu06r-006","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Japan: key events & terms","q":"Which is an accurate statement about Japan before Perry arrived?","options":["Trade and contact were controlled rather than entirely absent","No foreign goods ever entered Japan","Every Japanese citizen could freely travel abroad","Japan had no government"],"answer":0,"explain":"For example, limited Dutch and Chinese trade continued through Nagasaki.","id":"hu06r-007","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Japan: key events & terms","q":"What is industrialisation?","options":["Growth of mechanised production and factory industry","The closing of all schools","The replacement of all farms with temples","A system of hereditary warriors only"],"answer":0,"explain":"New technologies, infrastructure and manufacturing reshaped Japan.","id":"hu06r-008","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Japan: key events & terms","q":"Which development is an example of Japan’s military modernisation?","options":["Adoption of modern weapons and military organisation","A ban on all technology","Complete withdrawal from foreign affairs","The disappearance of the navy"],"answer":0,"explain":"Modernisation helped Japan build state and military capacity.","id":"hu06r-009","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Japan: key events & terms","q":"Which is a potential negative consequence of rapid modernisation?","options":["Disruption of traditional occupations and rising costs for some groups","No social change of any kind","An end to every form of education","Guaranteed equal benefit for everyone"],"answer":0,"explain":"Evaluate who benefited and who experienced costs, rather than assuming all changes were positive.","id":"hu06r-010","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Japan: evaluating significance","q":"Which argument best answers “To what extent did American intervention improve Japan”?","options":["It triggered important changes, but benefits and costs varied and Japanese reformers shaped the outcome","Everything that happened was good","Perry single-handedly created every Japanese factory","Japan never changed"],"answer":0,"explain":"An evaluative answer uses a qualified judgement and considers multiple causes.","id":"hu06r-011","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Japan: evaluating significance","q":"What evidence would best support a claim about economic impact?","options":["New trade routes and industrial development","The colour of Perry’s uniform","A present-day movie review","A map of Mexico"],"answer":0,"explain":"Choose evidence related to the impact being discussed.","id":"hu06r-012","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Japan: evaluating significance","q":"Why is it inaccurate to say the USA alone modernised Japan?","options":["Japanese political decisions and internal reforms were also crucial","The USA never visited Japan","Japan had no social institutions","Industrialisation had no connection with government"],"answer":0,"explain":"External pressure was a catalyst, not the only cause of change.","id":"hu06r-013","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Japan: evaluating significance","q":"Which pair presents contrasting effects of opening trade?","options":["New opportunities and possible disruption to established livelihoods","More and less rainfall","Two identical military victories","Two unrelated exam subjects"],"answer":0,"explain":"Good historical evaluation considers gains and losses.","id":"hu06r-014","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Japan: evaluating significance","q":"What does “most significant turning point” ask you to do?","options":["Compare importance and explain why one development mattered most","List dates without explanation","Describe only uniforms","Choose an answer by popularity"],"answer":0,"explain":"Use criteria such as scale, duration and consequences.","id":"hu06r-015","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Aztec conquest: events & impacts","q":"Which city fell to Spanish and Indigenous allied forces in 1521?","options":["Tenochtitlan","Kyoto","Osaka","Paris"],"answer":0,"explain":"The fall of the Mexica capital marked the end of the Aztec imperial centre.","id":"hu06r-016","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Aztec conquest: events & impacts","q":"Who led the Spanish expedition against the Mexica Empire?","options":["Hernán Cortés","Commodore Perry","Emperor Meiji","Tokugawa Yoshinobu"],"answer":0,"explain":"Cortés worked with Indigenous allies as well as Spanish forces.","id":"hu06r-017","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Aztec conquest: events & impacts","q":"What years are most closely associated with the Spanish conquest of the Aztec Empire?","options":["1519–1521","1853–1854","1868–1871","1914–1918"],"answer":0,"explain":"The expedition began in 1519; Tenochtitlan fell in 1521.","id":"hu06r-018","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Aztec conquest: events & impacts","q":"Why were Indigenous alliances important to the Spanish campaign?","options":["Allied groups contributed people, resources and local knowledge","The Spaniards faced no local opposition","Every Indigenous group supported the Mexica","Allies controlled Japanese trade"],"answer":0,"explain":"Do not present the conquest as a victory achieved by Spanish soldiers alone.","id":"hu06r-019","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Aztec conquest: events & impacts","q":"Why did smallpox have such a severe impact on Indigenous populations?","options":["Many people lacked prior immunity to introduced diseases","It was caused by a change in Japanese clothing","It affected only horses","It immediately cured other illnesses"],"answer":0,"explain":"Epidemics intensified demographic and social disruption.","id":"hu06r-020","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Aztec conquest: events & impacts","q":"What was a major political consequence of the conquest?","options":["Replacement of Mexica imperial rule by Spanish colonial control","An immediate return to identical local government","A new Japanese shogunate","The end of European colonisation"],"answer":0,"explain":"Spanish rule transformed political authority and land control.","id":"hu06r-021","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Aztec conquest: events & impacts","q":"How did Spanish colonisation affect religion?","options":["Catholic Christianity spread, often under pressure, while Indigenous practices also persisted or adapted","All Indigenous beliefs vanished instantly","There was no religious change","Japan became a Spanish colony"],"answer":0,"explain":"Avoid describing cultural change as total and immediate.","id":"hu06r-022","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Aztec conquest: events & impacts","q":"What economic changes followed conquest?","options":["Colonial control of land and resources and expanded mining or crop production","The complete end of agriculture","Only improved wages for everyone","No changes in trade networks"],"answer":0,"explain":"Economic consequences included exploitation and new colonial networks.","id":"hu06r-023","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Aztec conquest: events & impacts","q":"Which claim about Aztec culture is too absolute?","options":["Every cultural practice disappeared completely in 1521","The conquest disrupted political power","Some traditions continued in changed forms","Christianity spread under Spanish rule"],"answer":0,"explain":"Historical analysis should recognise both disruption and continuity.","id":"hu06r-024","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Aztec conquest: events & impacts","q":"Which comparison best distinguishes immediate from long-term consequences?","options":["Fall of Tenochtitlan versus generations of colonial cultural change","Two different names for the same ruler","A map title versus a legend","A date versus the same date"],"answer":0,"explain":"Historical significance can depend on both immediate and enduring effects.","id":"hu06r-025","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Source analysis & significance","q":"What is the most important limitation of Source A?","options":["It represents one colonial perspective and omits Indigenous experiences","It has no author at all","It contains a mathematical equation","It describes Japan in 1853"],"answer":0,"explain":"Identify the author’s standpoint, purpose and omissions.","passage":"Classroom source A (constructed summary): A Spanish colonial official praises the spread of Christianity and new trade. The statement does not describe the experiences of Indigenous communities.","id":"hu06r-026","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Source analysis & significance","q":"Which second source would most help assess the conquest’s impact on Indigenous people?","options":["An Indigenous account of social and cultural change","An unrelated modern advertisement","A Japanese railway timetable","A world weather map"],"answer":0,"explain":"Cross-check perspectives, while noting that no source is perfectly neutral.","passage":"Classroom source A (constructed summary): A Spanish colonial official praises the spread of Christianity and new trade. The statement does not describe the experiences of Indigenous communities.","id":"hu06r-027","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Source analysis & significance","q":"What is the strongest inference from Source B?","options":["Economic changes had uneven effects on different groups","Everyone benefited equally","No prices changed","Trade stopped completely"],"answer":0,"explain":"The two viewpoints show how the same change may help one group and harm another.","passage":"Classroom source B (constructed summary): A Japanese merchant reports gaining new trading opportunities after foreign contact, but another worker reports a rise in living costs.","id":"hu06r-028","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Source analysis & significance","q":"What should a historian check before generalising from these statements?","options":["Whether the accounts are representative and supported by other evidence","Whether the handwriting is colourful","How long the sentences are","Whether both authors used exactly the same words"],"answer":0,"explain":"Use provenance, context and corroboration to test a source.","passage":"Classroom source B (constructed summary): A Japanese merchant reports gaining new trading opportunities after foreign contact, but another worker reports a rise in living costs.","id":"hu06r-029","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Source analysis & significance","q":"Which criteria help judge historical significance?","options":["Extent, duration, depth and consequences of change","Font size and page margins","Only the number of names mentioned","Whether the source agrees with you"],"answer":0,"explain":"A significant event produces important and often lasting effects.","id":"hu06r-030","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Source analysis & significance","q":"In a “To what extent?” question, which opening is strongest?","options":["American intervention was an important catalyst, although internal Japanese reforms were also decisive.","Yes.","Perry arrived in 1853 and that is all.","I think history is interesting."],"answer":0,"explain":"Make a qualified judgement that you can substantiate.","id":"hu06r-031","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"TEEL historical arguments","q":"In Humanities TEEL, what is Evidence?","options":["A specific dated event, primary source detail or historical fact","A vague personal opinion","Repeating the question","The words “in conclusion”"],"answer":0,"explain":"Use material you can verify, not unsupported claims.","id":"hu06r-032","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"TEEL historical arguments","q":"Arrange a TEEL paragraph about Commodore Perry.","blocks":["Topic: Perry’s arrival was a significant catalyst for change in Japan.","Link: These events helped open a path toward wider changes, though Japanese reforms also mattered.","Evidence: Perry arrived in 1853, followed by the Treaty of Kanagawa in 1854.","Explain: It placed pressure on leaders to reconsider their restricted foreign relations."],"answer":[0,3,2,1],"explain":"TEEL explains the importance before introducing the supporting dated event.","id":"hu06r-033","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"TEEL historical arguments","q":"Arrange a TEEL paragraph about disease during the conquest.","blocks":["Topic: Disease was one of the most devastating effects of conquest.","Evidence: Smallpox spread among Indigenous populations during the Spanish campaign.","Explain: Epidemics caused widespread loss of life and weakened communities.","Link: Its demographic consequences extended beyond the military defeat of Tenochtitlan."],"answer":[0,2,1,3],"explain":"Identify an argument, explain its significance, support it with evidence, and link back.","id":"hu06r-034","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"TEEL historical arguments","q":"Which is a sound concluding judgement about the conquest?","options":["Military defeat was decisive, but disease and long-term colonial rule profoundly reshaped society.","Only one factor mattered and all others are irrelevant.","The conquest had no effects beyond 1521.","The Aztec Empire was in Japan."],"answer":0,"explain":"A strong conclusion weighs several forms of change.","id":"hu06r-035","source":"Original practice question based on supplied revision scope"},{"type":"short","area":"Japan: key events & terms","q":"Who led the US naval expedition that arrived in Japan in 1853?","answer":["commodore perry","perry","matthew perry","commodore matthew perry"],"explain":"Commodore Matthew Perry led the American expedition in 1853. The Convention of Kanagawa followed in 1854.","hint":"The surname begins with P.","source":"New guided revision written response","id":"hu06r-036"},{"type":"short","area":"Aztec conquest: events & impacts","q":"Name the Aztec capital that fell in 1521.","answer":["tenochtitlan","tenochtitlán"],"explain":"Tenochtitlan fell in 1521 to Cortés and his Indigenous allies, marking the end of the Mexica imperial capital.","hint":"It stood where modern Mexico City is located.","source":"New guided revision written response","id":"hu06r-037"},{"type":"short","area":"Japan: key events & terms","q":"What is the name for Japan’s historical policy of restricted foreign relations?","answer":["sakoku","the sakoku policy","sakoku policy"],"explain":"Sakoku refers to Edo-period restrictions on foreign contact, though some regulated trade continued.","hint":"The Japanese term starts with S.","source":"New guided revision written response","id":"hu06r-038"}],"french":[{"type":"mc","area":"Family & appearance","q":"What does “ma cousine” mean?","options":["My female cousin","My grandfather","My aunt","My male cousin"],"answer":0,"explain":"Ma is used with a feminine noun here.","id":"fr06r-001","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Family & appearance","q":"Which phrase means “my parents”?","options":["Mes parents","Mon frère","Ma sœur","Tes amis"],"answer":0,"explain":"Mes is the plural possessive adjective.","id":"fr06r-002","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"Family & appearance","q":"Arrange the French for “I have one brother and two sisters.”","blocks":["et","un frère","J’ai","deux sœurs."],"answer":[2,1,0,3],"explain":"The sentence begins with J’ai, meaning I have.","id":"fr06r-003","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Family & appearance","q":"What does “Il a les yeux verts” mean?","options":["He has green eyes","He has brown hair","He is tall","He has two brothers"],"answer":0,"explain":"Yeux means eyes; verts means green (plural).","id":"fr06r-004","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Family & appearance","q":"Which phrase means “She is tall and kind”?","options":["Elle est grande et gentille.","Il est grand et gentil.","Elle a grand et gentil.","Elle est grands et gentils."],"answer":0,"explain":"Adjectives generally agree with the person described.","id":"fr06r-005","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Family & appearance","q":"Choose the correct adjective: “Mon frère est ___.” (sporty)","options":["sportif","sportive","sportifs","sportives"],"answer":0,"explain":"Mon frère is masculine singular.","id":"fr06r-006","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Family & appearance","q":"Choose the correct adjective: “Ma sœur est ___.” (sporty)","options":["sportive","sportif","sportifs","sportives"],"answer":0,"explain":"Ma sœur is feminine singular.","id":"fr06r-007","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Family & appearance","q":"Complete: “Ma mère a les cheveux ___.” (brown)","options":["bruns","brune","brun","brunes"],"answer":0,"explain":"Cheveux is masculine plural, so brun becomes bruns.","id":"fr06r-008","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Family & appearance","q":"What does “drôle” usually mean when describing a person?","options":["Funny","Angry","Sad","Tall"],"answer":0,"explain":"Drôle is a useful appearance/personality adjective.","id":"fr06r-009","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Family & appearance","q":"Which sentence correctly describes two sisters as shy?","options":["Mes sœurs sont timides.","Mes sœurs est timide.","Ma sœurs sont timide.","Mes sœur est timides."],"answer":0,"explain":"Plural subject uses sont; adjective timides is plural.","id":"fr06r-010","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"School & marks","q":"What is “les sciences” at school?","options":["Science","History","Physical education","Art"],"answer":0,"explain":"Science is les sciences in French.","id":"fr06r-011","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"School & marks","q":"What does “J’ai eu quinze sur vingt en français” mean?","options":["I got 15 out of 20 in French","I have 20 French books","I study French at 3:20","I will leave French in 15 minutes"],"answer":0,"explain":"J’ai eu means I got; sur vingt means out of twenty.","id":"fr06r-012","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"School & marks","q":"Build “I like history because it is interesting.”","blocks":["J’aime","parce que","l’histoire","c’est intéressant."],"answer":[0,2,1,3],"explain":"J’aime + subject + parce que + reason.","id":"fr06r-013","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"School & marks","q":"Translate “les maths sont difficiles”.","options":["Maths is difficult","Maths is easy","I love maths","School begins early"],"answer":0,"explain":"Difficiles describes maths; plural agrees with les maths.","id":"fr06r-014","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"School & marks","q":"What does “Quelle note as-tu eue ?” ask?","options":["What mark did you get?","What time is it?","Where is your classroom?","How old are you?"],"answer":0,"explain":"Une note means a mark or grade in this context.","id":"fr06r-015","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Daily routine & leisure","q":"What does “Je me lève à sept heures” mean?","options":["I get up at seven o’clock","I go to bed at seven","I eat at seven","I arrive at school at eight"],"answer":0,"explain":"Se lever means to get up.","id":"fr06r-016","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Daily routine & leisure","q":"Translate “faire du vélo”.","options":["To go cycling","To play football","To read","To go swimming"],"answer":0,"explain":"Faire du vélo means to cycle.","id":"fr06r-017","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"Daily routine & leisure","q":"Build “After school, I play football.”","blocks":["je joue","au foot.","Après l’école,"],"answer":[2,0,1],"explain":"Je joue au foot = I play football.","id":"fr06r-018","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Daily routine & leisure","q":"Which phrase means “I go to bed at ten”?","options":["Je me couche à dix heures.","Je me lève à dix heures.","Je me lave à dix heures.","Je mange dix heures."],"answer":0,"explain":"Se coucher is the reflexive verb for going to bed.","id":"fr06r-019","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Daily routine & leisure","q":"What does “J’aime écouter de la musique” mean?","options":["I like listening to music","I like taking photos","I am going to dance","I dislike music"],"answer":0,"explain":"Écouter means to listen.","id":"fr06r-020","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Near future: aller","q":"Complete: “Nous ___ regarder un film.”","options":["allons","allez","vais","va"],"answer":0,"explain":"Nous allons + infinitive is near future.","hint":"Remember aller: je vais, tu vas, il/elle va, nous allons, vous allez, ils/elles vont.","id":"fr06r-021","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Near future: aller","q":"Complete: “Elle ___ au cinéma demain.”","options":["va","vais","allons","vont"],"answer":0,"explain":"Elle va is third-person singular present of aller.","id":"fr06r-022","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Near future: aller","q":"What does “Je vais visiter ma grand-mère” mean?","options":["I am going to visit my grandmother","I visited my grandmother yesterday","I never visit my grandmother","I have a grandmother"],"answer":0,"explain":"Aller (conjugated) + infinitive = near future.","id":"fr06r-023","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"Near future: aller","q":"Build “Tomorrow they are going to play basketball.”","blocks":["jouer","ils vont","au basket.","Demain,"],"answer":[3,1,0,2],"explain":"Ils vont + jouer. The main verb stays in the infinitive.","id":"fr06r-024","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"Near future: aller","q":"Build “We are going to play football on Saturday.”","blocks":["Nous allons","jouer","samedi.","au foot"],"answer":[0,1,3,2],"explain":"Nous allons is followed by the infinitive jouer.","id":"fr06r-025","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Near future: aller","q":"Which is the CORRECT near-future sentence?","options":["Tu vas manger.","Tu va manger.","Tu vas manges.","Tu allait manger."],"answer":0,"explain":"After the conjugated aller, use the infinitive.","id":"fr06r-026","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Time & meeting arrangements","q":"What time is “huit heures et quart”?","options":["8:15","8:45","7:15","8:30"],"answer":0,"explain":"Et quart means quarter past.","id":"fr06r-027","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Time & meeting arrangements","q":"What time is “neuf heures moins le quart”?","options":["8:45","9:15","9:45","8:15"],"answer":0,"explain":"Moins le quart means quarter to the next hour.","id":"fr06r-028","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Time & meeting arrangements","q":"What does “à seize heures trente” mean?","options":["4:30 pm","6:30 pm","4:30 am","5:15 pm"],"answer":0,"explain":"Sixteen hours thirty is 16:30 in 24-hour time.","id":"fr06r-029","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"Time & meeting arrangements","q":"Arrange a meeting: “We meet in front of the cinema at 4:30 pm.”","blocks":["devant le cinéma","On se retrouve","à seize heures trente."],"answer":[1,0,2],"explain":"On se retrouve = we meet; devant = in front of.","id":"fr06r-030","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Time & meeting arrangements","q":"What is the best reply to “À quelle heure on se retrouve ?”","options":["À quinze heures.","J’ai treize ans.","Je suis sportif.","J’ai un frère."],"answer":0,"explain":"The question asks what time you will meet.","id":"fr06r-031","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"Grammar, negatives & sentence building","q":"Build “I do not like French.”","blocks":["pas","n’aime","Je","le français."],"answer":[2,1,0,3],"explain":"Ne (n’) goes before the conjugated verb and pas after it.","id":"fr06r-032","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"Grammar, negatives & sentence building","q":"Build “She is not shy.”","blocks":["timide.","n’est","pas","Elle"],"answer":[3,1,2,0],"explain":"Before a vowel or silent h, ne becomes n’.","id":"fr06r-033","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Grammar, negatives & sentence building","q":"Why is “n’aime” written with an apostrophe?","options":["Ne contracts before a vowel","It makes the verb plural","The sentence is in the future","All French verbs require an apostrophe"],"answer":0,"explain":"Ne becomes n’ before a vowel or mute h.","id":"fr06r-034","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"Grammar, negatives & sentence building","q":"Build “Tomorrow, I am not going to watch television.”","blocks":["la télé.","Demain,","regarder","je ne vais pas"],"answer":[1,3,2,0],"explain":"In the negative near future, ne ... pas surrounds the conjugated aller.","id":"fr06r-035","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Grammar, negatives & sentence building","q":"Complete: “Tu ___ un chien.”","options":["as","a","ai","avons"],"answer":0,"explain":"Tu as is the present tense of avoir (to have).","id":"fr06r-036","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Grammar, negatives & sentence building","q":"Complete: “Vous ___ vos devoirs.”","options":["faites","fais","fait","faisons"],"answer":0,"explain":"Vous faites is the present tense of faire.","id":"fr06r-037","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Grammar, negatives & sentence building","q":"Complete: “Je ___ lave le matin.”","options":["me","te","se","nous"],"answer":0,"explain":"Je me lave is a reflexive verb: I wash myself.","id":"fr06r-038","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Grammar, negatives & sentence building","q":"Complete: “Nous ___ français en classe.” (parler)","options":["parlons","parlez","parle","parlent"],"answer":0,"explain":"Regular -er endings: nous ...ons.","id":"fr06r-039","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"Grammar, negatives & sentence building","q":"Arrange “My brother is funny.”","blocks":["Mon frère","drôle.","est"],"answer":[0,2,1],"explain":"Mon = my before a masculine noun; est = is.","id":"fr06r-040","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Reading a short passage","q":"Quel âge a Léa ?","options":["13 ans","12 ans","14 ans","15 ans"],"answer":0,"explain":"J’ai treize ans = I am thirteen years old.","passage":"Lis le texte (original practice paragraph): Je m’appelle Léa et j’ai treize ans. J’habite avec ma mère et mon frère à Lyon. Mon collège commence à huit heures trente. Je préfère les sciences, mais je n’aime pas les maths. Après l’école, je fais du vélo. Mon amie Chloé est grande et très drôle. Samedi, nous allons nous retrouver devant la bibliothèque à quinze heures.","id":"fr06r-041","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Reading a short passage","q":"Avec qui habite-t-elle ?","options":["Sa mère et son frère","Son père et sa sœur","Ses grands-parents","Son cousin"],"answer":0,"explain":"Elle dit: ma mère et mon frère.","passage":"Lis le texte (original practice paragraph): Je m’appelle Léa et j’ai treize ans. J’habite avec ma mère et mon frère à Lyon. Mon collège commence à huit heures trente. Je préfère les sciences, mais je n’aime pas les maths. Après l’école, je fais du vélo. Mon amie Chloé est grande et très drôle. Samedi, nous allons nous retrouver devant la bibliothèque à quinze heures.","id":"fr06r-042","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Reading a short passage","q":"À quelle heure commence son collège ?","options":["8 h 30","7 h 15","9 h 00","15 h 00"],"answer":0,"explain":"Huit heures trente = 8:30.","passage":"Lis le texte (original practice paragraph): Je m’appelle Léa et j’ai treize ans. J’habite avec ma mère et mon frère à Lyon. Mon collège commence à huit heures trente. Je préfère les sciences, mais je n’aime pas les maths. Après l’école, je fais du vélo. Mon amie Chloé est grande et très drôle. Samedi, nous allons nous retrouver devant la bibliothèque à quinze heures.","id":"fr06r-043","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Reading a short passage","q":"Quelle matière préfère Léa ?","options":["Les sciences","Les maths","Le français","L’histoire"],"answer":0,"explain":"Je préfère les sciences means I prefer science.","passage":"Lis le texte (original practice paragraph): Je m’appelle Léa et j’ai treize ans. J’habite avec ma mère et mon frère à Lyon. Mon collège commence à huit heures trente. Je préfère les sciences, mais je n’aime pas les maths. Après l’école, je fais du vélo. Mon amie Chloé est grande et très drôle. Samedi, nous allons nous retrouver devant la bibliothèque à quinze heures.","id":"fr06r-044","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Reading a short passage","q":"Que fait Léa après l’école ?","options":["Elle fait du vélo.","Elle joue au tennis.","Elle dort.","Elle va au cinéma."],"answer":0,"explain":"Faire du vélo means to cycle.","passage":"Lis le texte (original practice paragraph): Je m’appelle Léa et j’ai treize ans. J’habite avec ma mère et mon frère à Lyon. Mon collège commence à huit heures trente. Je préfère les sciences, mais je n’aime pas les maths. Après l’école, je fais du vélo. Mon amie Chloé est grande et très drôle. Samedi, nous allons nous retrouver devant la bibliothèque à quinze heures.","id":"fr06r-045","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Reading a short passage","q":"Où et quand retrouve-t-elle Chloé ?","options":["Devant la bibliothèque samedi à 15 h","Au cinéma vendredi à 16 h","À l’école lundi à 8 h","Au parc dimanche à midi"],"answer":0,"explain":"Devant la bibliothèque = outside/in front of the library.","passage":"Lis le texte (original practice paragraph): Je m’appelle Léa et j’ai treize ans. J’habite avec ma mère et mon frère à Lyon. Mon collège commence à huit heures trente. Je préfère les sciences, mais je n’aime pas les maths. Après l’école, je fais du vélo. Mon amie Chloé est grande et très drôle. Samedi, nous allons nous retrouver devant la bibliothèque à quinze heures.","id":"fr06r-046","source":"Original practice question based on supplied revision scope"},{"type":"short","area":"Near future: aller","q":"Write the present-tense form of aller for “nous”.","answer":["allons","nous allons"],"explain":"Nous allons + infinitive makes the near future, e.g. nous allons jouer.","hint":"je vais, tu vas, il va, nous ...","source":"New guided revision written response","id":"fr06r-047"},{"type":"short","area":"Grammar, negatives & sentence building","q":"Translate “I do not like French”.","answer":["je n’aime pas le français","je n aime pas le français","je n'aime pas le français"],"explain":"Negation surrounds the conjugated verb: ne/n’ + aime + pas. The apostrophe comes before a vowel.","hint":"Use ne ... pas around aime.","source":"New guided revision written response","id":"fr06r-048"},{"type":"short","area":"Grammar, negatives & sentence building","q":"Translate “My sister is sporty”.","answer":["ma sœur est sportive","ma soeur est sportive"],"explain":"For a feminine subject, sportif generally becomes sportive. Ma sœur = my sister.","hint":"The feminine adjective ends in -ive.","source":"New guided revision written response","id":"fr06r-049"},{"type":"short","area":"Daily routine & leisure","q":"Write “I get up” in French.","answer":["je me lève","je me leve"],"explain":"Se lever is reflexive: je me lève, tu te lèves, il/elle se lève.","hint":"Include the reflexive pronoun me.","source":"New guided revision written response","id":"fr06r-050"}],"maths":[{"type":"mc","area":"Integers, indices & fractions","q":"Calculate 2 + (−5 × −3) − (−4).","options":["21","−17","13","−9"],"answer":0,"explain":"Multiply first: −5 × −3 = +15, then 2 + 15 + 4 = 21.","id":"ma06r-001","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Integers, indices & fractions","q":"Evaluate (−8)².","answer":64,"explain":"Squaring −8 means (−8) × (−8) = 64.","tolerance":1e-05,"id":"ma06r-002","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Integers, indices & fractions","q":"Simplify 3⁵ ÷ 3².","options":["3³","3⁷","1³","6³"],"answer":0,"explain":"When dividing powers with the same base, subtract exponents.","id":"ma06r-003","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Integers, indices & fractions","q":"What is 12.5% as a fraction in simplest form?","options":["1/8","1/4","1/12","1/80"],"answer":0,"explain":"12.5% = 12.5/100 = 0.125 = 1/8.","id":"ma06r-004","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Integers, indices & fractions","q":"What is 2.18 as a mixed number in simplest form?","options":["2 9/50","2 18/10","2 1/8","2 9/10"],"answer":0,"explain":"0.18 = 18/100 = 9/50.","id":"ma06r-005","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Integers, indices & fractions","q":"Find the highest common factor of 48 and 56.","options":["8","7","12","16"],"answer":0,"explain":"48 = 8 × 6 and 56 = 8 × 7; there is no larger common factor.","id":"ma06r-006","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Integers, indices & fractions","q":"What is the lowest common multiple of 48 and 56?","answer":336,"explain":"48=2⁴×3 and 56=2³×7, so LCM=2⁴×3×7=336.","tolerance":1e-05,"id":"ma06r-007","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Integers, indices & fractions","q":"The mean of 23, 25 and x is 26. Find x.","answer":30,"explain":"(23+25+x) ÷ 3 = 26, so x = 78 − 48 = 30.","tolerance":1e-05,"id":"ma06r-008","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Algebra & equations","q":"Solve 4y + 2 = 2y + 6. Enter y.","answer":2,"explain":"Subtract 2y: 2y+2=6. Subtract 2 and divide by 2: y=2.","tolerance":1e-05,"id":"ma06r-009","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Algebra & equations","q":"Solve 5x − 2 = 3x + 8. Enter x.","answer":5,"explain":"2x=10, so x=5.","tolerance":1e-05,"id":"ma06r-010","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Algebra & equations","q":"Solve (2x ÷ 5) − 1 = 7. Enter x.","answer":20,"explain":"Add 1: 2x/5=8, multiply by 5: 2x=40, so x=20.","tolerance":1e-05,"id":"ma06r-011","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Algebra & equations","q":"Solve 3(x + 4) = 2(1 − x). Enter x.","answer":-2,"explain":"Expand: 3x+12=2−2x. Rearrange: 5x=−10, so x=−2.","tolerance":1e-05,"id":"ma06r-012","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Algebra & equations","q":"Simplify 4x² + 8x − 7x³ − 4x² − 3x.","options":["5x − 7x³","5x³","8x − 7x³","−7x³ + 12x²"],"answer":0,"explain":"The x² terms cancel; 8x − 3x = 5x.","id":"ma06r-013","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Algebra & equations","q":"Factorise 3x + 6.","options":["3(x + 2)","3(x + 6)","x(3 + 6)","6(x + 3)"],"answer":0,"explain":"Find the highest common factor: 3.","id":"ma06r-014","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Algebra & equations","q":"Expand (x + 2)².","options":["x² + 4x + 4","x² + 4","x² + 2x + 4","2x² + 4x"],"answer":0,"explain":"(x+2)(x+2) = x²+2x+2x+4.","id":"ma06r-015","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"Algebra & equations","q":"Arrange the working to solve 3(x + 4) = 2(1 − x).","blocks":["Expand: 3x + 12 = 2 − 2x","Collect terms: 5x + 12 = 2","Divide by 5: x = −2","Subtract 12: 5x = −10"],"answer":[0,1,3,2],"explain":"Apply each inverse operation to both sides.","id":"ma06r-016","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Algebra & equations","q":"Which expression means “six is added to four times a number to give thirty”?","options":["4x + 6 = 30","6x + 4 = 30","4x − 6 = 30","4 + 6 = 30"],"answer":0,"explain":"Four times x is 4x, then add 6.","id":"ma06r-017","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Ratio, percentages & rates","q":"Simplify the ratio 50 g : 4 kg.","options":["1 : 80","50 : 4","1 : 8","5 : 4"],"answer":0,"explain":"Convert 4 kg to 4000 g; 50:4000 = 1:80.","id":"ma06r-018","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Ratio, percentages & rates","q":"Share 45 jellybeans in the ratio 1:4. What are the two shares?","options":["9 and 36","15 and 30","5 and 40","1 and 4"],"answer":0,"explain":"Five total parts means 45÷5=9 in each part; shares 9 and 36.","id":"ma06r-019","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Ratio, percentages & rates","q":"A footballer scores 16 of a team’s 52 goals. What percentage is that? Give 2 decimal places.","answer":30.77,"explain":"16÷52×100 = 30.769...%, which rounds to 30.77%.","tolerance":0.011,"unit":"%","id":"ma06r-020","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Ratio, percentages & rates","q":"A car uses 72 L of fuel over 840 km. What is its fuel consumption in L/100 km? Give 2 decimal places.","answer":8.57,"explain":"72÷840×100 = 8.571... L/100 km.","tolerance":0.011,"unit":"L/100 km","id":"ma06r-021","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Ratio, percentages & rates","q":"A rectangle is 20 cm by 80 cm by 50 cm as a prism. How many litres can it hold?","answer":80,"explain":"Volume = 20×80×50 = 80,000 cm³. Since 1000 cm³=1 L, the capacity is 80 L.","tolerance":1e-05,"unit":"L","id":"ma06r-022","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Statistics & probability","q":"Which is the median of 5, 9, 17, 25, 36, 45?","options":["21","17","25","27"],"answer":0,"explain":"With six values, average the middle two: (17+25)/2=21.","id":"ma06r-023","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Statistics & probability","q":"For the sorted data 5, 9, 17, 25, 36, 45, find the IQR using medians of each half.","answer":27,"explain":"Lower half 5,9,17 has Q1=9. Upper half 25,36,45 has Q3=36. IQR=27.","tolerance":1e-05,"id":"ma06r-024","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Statistics & probability","q":"In the provided stem-and-leaf diagram, what is the smallest number?","options":["12","23","31","40"],"answer":0,"explain":"The first leaf 2 on stem 1 stands for 12.","visual":"stemleaf","id":"ma06r-025","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Statistics & probability","q":"What is the best definition of an outlier?","options":["A value unusually far from the rest of the data","The most frequent value","The middle value","A ratio in simplest form"],"answer":0,"explain":"Outliers may influence the mean and should be investigated.","id":"ma06r-026","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Statistics & probability","q":"At a zoo, 59 visitors bought at the café, 24 at the shop, and 17 bought at both. How many bought at the café only?","options":["42","17","7","59"],"answer":0,"explain":"Café only = 59 − 17 = 42.","visual":"venn","id":"ma06r-027","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Statistics & probability","q":"In the same zoo problem (75 visitors total), how many bought at neither place?","options":["9","17","7","24"],"answer":0,"explain":"Union=59+24−17=66; neither=75−66=9.","visual":"venn","id":"ma06r-028","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Statistics & probability","q":"In the zoo problem, what is the probability a visitor bought from exactly one location?","options":["49/75","17/75","66/75","59/75"],"answer":0,"explain":"Café-only 42 plus shop-only 7 gives 49 out of 75.","visual":"venn","id":"ma06r-029","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Statistics & probability","q":"If P(A)=0.7, what is P(not A)?","options":["0.3","0.7","1.7","0.07"],"answer":0,"explain":"Complement rule: P(A′)=1−P(A).","id":"ma06r-030","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Statistics & probability","q":"In a class, 59 did both Maths and English homework, 11 only English, 14 only Maths, 23 neither. How many students altogether?","options":["107","73","70","96"],"answer":0,"explain":"Add all four regions: 59+11+14+23=107.","visual":"twoway","id":"ma06r-031","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Statistics & probability","q":"From that class, what is the probability someone completed Maths given they completed English?","options":["59/70","59/107","14/37","11/70"],"answer":0,"explain":"Among English completers, 59 did Maths and 11 did not; there are 70.","visual":"twoway","id":"ma06r-032","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Measurement, geometry & graphs","q":"A right triangle has perpendicular sides 3 cm and 4 cm. What is its hypotenuse?","answer":5,"explain":"Pythagoras: c²=3²+4²=25, so c=5 cm.","tolerance":1e-05,"unit":"cm","visual":"triangle","id":"ma06r-033","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Measurement, geometry & graphs","q":"A right triangle has perpendicular sides 19 cm and 32 cm. Find the hypotenuse to 2 decimal places.","answer":37.22,"explain":"c=√(19²+32²)=√1385≈37.22 cm.","tolerance":0.011,"unit":"cm","id":"ma06r-034","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Measurement, geometry & graphs","q":"A circle has diameter 34 cm. Find its area to 2 decimal places.","answer":907.92,"explain":"Radius=17 cm. Area=π×17²≈907.92 cm².","tolerance":0.011,"unit":"cm²","id":"ma06r-035","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Measurement, geometry & graphs","q":"A rectangle measuring 35 cm × 25 cm has two semicircles (diameter 25 cm) removed. Find the remaining area to 2 decimals.","answer":384.13,"explain":"Rectangle area=875. Two semicircles equal one circle with radius 12.5: 875−π×12.5²≈384.13 cm².","tolerance":0.011,"unit":"cm²","visual":"composite","id":"ma06r-036","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Measurement, geometry & graphs","q":"An annulus has outer radius 12 m and inner radius 7 m. Find its area to 2 decimal places.","answer":298.45,"explain":"Area=π(12²−7²)=95π≈298.45 m².","tolerance":0.011,"unit":"m²","id":"ma06r-037","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Measurement, geometry & graphs","q":"A rectangular prism measures 45 cm × 50 cm × 60 cm. Find total surface area.","answer":15900,"explain":"TSA=2(lw+lh+wh)=2(2250+2700+3000)=15,900 cm².","tolerance":1e-05,"unit":"cm²","id":"ma06r-038","source":"Original practice question based on supplied revision scope"},{"type":"number","area":"Measurement, geometry & graphs","q":"A triangle has sides in the ratio 3:4:5. If the longest is 40 cm, what is the perimeter?","answer":96,"explain":"Five parts=40, so each part=8. Sides 24,32,40; perimeter 96 cm.","tolerance":1e-05,"unit":"cm","id":"ma06r-039","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Measurement, geometry & graphs","q":"What is the correct area conversion?","options":["1 m² = 10,000 cm²","1 m² = 100 cm²","1 m² = 1000 cm²","1 m² = 1,000,000 cm²"],"answer":0,"explain":"1 m = 100 cm; squaring gives 100×100=10,000.","id":"ma06r-040","source":"Original practice question based on supplied revision scope"},{"type":"mc","area":"Measurement, geometry & graphs","q":"Which rule passes through the points (2,5) and (9,40)?","options":["y = 5x − 5","y = 5x + 5","y = x + 3","y = 7x − 9"],"answer":0,"explain":"Gradient=(40−5)/(9−2)=5. Intercept=5−5×2=−5.","id":"ma06r-041","source":"Original practice question based on supplied revision scope"},{"type":"blocks","area":"Measurement, geometry & graphs","q":"Arrange the standard working for a surface area problem.","blocks":["Calculate each product and the total.","State the answer with squared units.","Substitute the measured lengths.","Write the formula: TSA = 2(lw + lh + wh)."],"answer":[3,2,0,1],"explain":"The teacher’s method is Formula → Substitute → Solve, including units.","id":"ma06r-042","source":"Original practice question based on supplied revision scope"},{"type":"short","area":"Algebra & equations","q":"What does the abbreviation HCF stand for?","answer":["highest common factor","highest common factor (hcf)"],"explain":"The highest common factor is the largest whole number that divides two or more numbers exactly.","hint":"The answer has three words.","source":"New guided revision written response","id":"ma06r-043"},{"type":"short","area":"Measurement, geometry & graphs","q":"What does the A in V = A × h represent for a prism?","answer":["area","area of cross section","area of the cross section","cross sectional area","cross-sectional area"],"explain":"The volume of a prism is the area of its constant cross-section multiplied by its length/height.","hint":"A stands for area of the repeated face.","source":"New guided revision written response","id":"ma06r-044"}]};
